import { X509Certificate } from "node:crypto";
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { generate } from "selfsigned";

// Local certificate authority for the stand-in bank (D12), generated by npm run setup (and by db:reset if missing).
// Development tooling only: the app never imports this module, and selfsigned is a dev dependency. Files in PKI_DIR:
//   ca.pem / ca-key.pem                         the local CA (its key stays here; real CAs keep it offline)
//   bank.pem / bank-key.pem                     the bank's TLS server certificate (localhost, 127.0.0.1)
//   payrollhub-client.pem / -key.pem            PayrollHub's client certificate for mTLS (CN payrollhub-ach)
//   bank-pin.txt                                SHA-256 fingerprint of bank.pem: the certificate PayrollHub pins

export const CLIENT_CN = "payrollhub-ach";

export interface Pem {
  cert: string;
  key: string;
}

// A day of slack on notBefore, so a test's fake clock cannot make a fresh certificate "not yet valid".
const validity = () => ({ notBeforeDate: new Date(Date.now() - 86_400_000), notAfterDate: new Date(Date.now() + 825 * 86_400_000) });

export async function generateCa(name = "PayrollHub Local Dev CA"): Promise<Pem> {
  const ca = await generate([{ name: "commonName", value: name }], {
    keyType: "ec",
    curve: "P-256",
    algorithm: "sha256",
    ...validity(),
    extensions: [
      { name: "basicConstraints", cA: true, critical: true },
      { name: "keyUsage", keyCertSign: true, cRLSign: true, critical: true },
    ],
  });
  return { cert: ca.cert, key: ca.private };
}

/** A leaf certificate signed by the given CA (serverAuth and clientAuth; localhost also gets 127.0.0.1). */
export async function issueCert(ca: Pem, commonName: string): Promise<Pem> {
  const leaf = await generate([{ name: "commonName", value: commonName }], {
    keyType: "ec",
    curve: "P-256",
    algorithm: "sha256",
    ...validity(),
    ca: { key: ca.key, cert: ca.cert },
  });
  return { cert: leaf.cert, key: leaf.private };
}

export const fingerprint = (certPem: string) => new X509Certificate(certPem).fingerprint256;

/** Creates the CA, the bank's server certificate, PayrollHub's client certificate, and the pin. Idempotent. */
export async function provisionPki(dir: string): Promise<boolean> {
  if (existsSync(join(dir, "ca.pem"))) return false;
  mkdirSync(dir, { recursive: true });
  const ca = await generateCa();
  const bank = await issueCert(ca, "localhost");
  const client = await issueCert(ca, CLIENT_CN);
  const write = (file: string, data: string) => writeFileSync(join(dir, file), data, { mode: 0o600 });
  write("ca-key.pem", ca.key);
  write("bank.pem", bank.cert);
  write("bank-key.pem", bank.key);
  write("payrollhub-client.pem", client.cert);
  write("payrollhub-client-key.pem", client.key);
  write("bank-pin.txt", `${fingerprint(bank.cert)}\n`);
  write("ca.pem", ca.cert); // last: its presence marks a complete set
  return true;
}
